/**
 * RMHHomes — AI listing-image generation API.
 *
 * POST /api/homes/ai-image  { prompt }  → { url }
 *
 * Auth-gated and tightly rate-limited (each call is a paid xAI generation).
 * Returns the stored image URL; the client adds it to the listing's photos and
 * marks it AI-generated so the "Generated by AI" disclaimer shows.
 */
import { createFileRoute } from '@tanstack/react-router';
import { implement } from '@/lib/api/implement.server';
import { generateHomeAiImageApi, getHomeAiImageAvailabilityApi } from '@/lib/homes/homes.contract';
import { z } from 'zod';
import { generateListingImage, isListingImageAIConfigured } from '@/lib/homes/ai-image.server';

const schema = z.object({ prompt: z.string().min(1).max(500) });

export const Route = createFileRoute('/api/homes/ai-image')({
  server: {
    handlers: {
      GET: implement(getHomeAiImageAvailabilityApi, {}, async () => ({
        available: isListingImageAIConfigured(),
      })),

      POST: implement(
        generateHomeAiImageApi,
        {
          rateLimit: {
            limit: 10,
            windowMs: 60_000,
            prefix: 'homes-ai-image',
            message: 'Slow down — too many image generations.',
          },
          body: schema,
          invalid: () => Response.json({ error: 'Enter a description to generate.' }, { status: 400 }),
        },
        async ({ session, body }) => {
          const result = await generateListingImage(session.user.id, body.prompt);
          if ('error' in result) {
            return Response.json({ error: result.error }, { status: 502 });
          }
          return { url: result.url };
        },
      ),
    },
  },
});
